19	/* M5Unified reads the buttons as active-low GPIOs, and only inside
20	 * M5.update(), so a press during a long hack step would go unseen. A small
21	 * task on the otherwise idle core 0 samples both pins every few milliseconds
22	 * (it preempts nothing the hacks run on) and a latch keeps the presses. The
23	 * pin must hold its new level for the settle time, which rejects bounce. */
24	static const gpio_num_t kPinButtonA = GPIO_NUM_2;
25	static const gpio_num_t kPinButtonB = GPIO_NUM_1;
26	static const uint32_t kButtonPollMs = 5;
