114	void loop() {
115	  M5.update();
116	  pollButtons();
117	
118	  uint32_t t0 = micros();
119	  unsigned long delayUs = runner_step(runner);
120	  uint32_t t1 = micros();
121	  M5.Display.pushImage(0, 0, kSize, kSize, canvas.px);
122	  uint32_t t2 = micros();
123	  frames++;
124	  stepUs += t1 - t0;
125	  pushUs += t2 - t1;
126	
127	  /* Only the push counts against the delay. A hack's delay is the pause after
128	   * it draws, so a hack that asks for a one-second hold must still get it
129	   * however long its own step took. */
130	  unsigned long waitUsTarget = runner_remaining_delay_us(delayUs, t2 - t1);
131	  uint32_t waitedUs = 0;
132	  bool switched = false;
133	  while (!switched && waitedUs < waitUsTarget) {
134	    uint32_t slice =
135	        waitUsTarget - waitedUs < kSliceUs ? waitUsTarget - waitedUs : kSliceUs;
136	    delayMicroseconds(slice);
137	    waitedUs += slice;
138	    M5.update();
139	    switched = pollButtons();
140	  }
141	  if (!switched) waitUs += micros() - t2;
142	
143	  if (millis() - statsAt >= kStatsEveryMs) {
144	    printStats("run");
145	    resetStats();
